<script setup lang="ts">
import { computed,onMounted,onUnmounted,ref } from 'vue'
import { NAlert,NButton,NEmpty,NIcon,NProgress,NSpin,NTag,useMessage } from 'naive-ui'
import { ArrowUpRight,ArrowDownRight,Server,Users,Refresh,ArrowRight,Activity } from '@vicons/tabler'
import { api,bytes,stamp } from '../api'
const props=defineProps<{me:any;zone:string}>();const emit=defineEmits(['usage','refresh-account'])
const stats=ref<any>({}),nodes=ref<any[]>([]),usage=ref<any[]>([]),busy=ref(true),error=ref('');let timer:ReturnType<typeof setInterval>|undefined;const message=useMessage()
async function load(){error.value='';try{const jobs=[api('/api/dashboard'),api('/api/usage?grain=day&timezone='+encodeURIComponent(props.zone))];if(props.me.role==='admin')jobs.push(api('/api/admin/nodes'));const data=await Promise.all(jobs);stats.value=data[0];usage.value=data[1].rows;nodes.value=data[2]||[];emit('refresh-account')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
const bars=computed(()=>{const grouped=new Map<string,number>();for(const row of usage.value){const date=row.bucket.slice(0,10);grouped.set(date,(grouped.get(date)||0)+Number(row.up_bytes)+Number(row.down_bytes))}const entries=[...grouped].sort(([a],[b])=>a.localeCompare(b));const max=Math.max(...entries.map(x=>x[1]),1);return entries.map(([date,total])=>({date,total,height:Math.max(total/max*100,2)}))})
const quotaProgress=computed(()=>props.me.quota_bytes?Math.min(props.me.used_bytes/props.me.quota_bytes*100,100):0)
function currentWindow(node:any){return online(node)&&node.last_period_end&&Date.now()-Date.parse(node.last_period_end)<node.report_interval*3000}
function online(node:any){return node.last_report_at&&(Date.now()-Date.parse(node.last_report_at))/1000<node.report_interval*3}
onMounted(()=>{load();timer=setInterval(load,30000)});onUnmounted(()=>clearInterval(timer))
</script>
<template><div class="page-heading"><div><span class="eyebrow">OVERVIEW</span><h1>运行概览<span class="heading-dot"></span></h1><p>节点、用户与用量，一目了然。</p></div><n-button secondary :loading="busy" @click="load"><template #icon><n-icon :component="Refresh"/></template>刷新数据</n-button></div><n-alert v-if="error" type="error" class="space-bottom">{{error}}</n-alert><n-spin :show="busy"><section class="stat-grid"><article class="stat-card"><span class="stat-label">{{me.role==='admin'?'全部用户':'我的额度'}}</span><n-icon class="stat-icon" :component="Users"/><strong>{{me.role==='admin'?stats.total_users??'—':bytes(me.quota_bytes)}}</strong><small>{{me.role==='admin'?'已创建的账户':'到期时间 '+stamp(me.expires_at)}}</small></article><article class="stat-card"><span class="stat-label">在线节点</span><n-icon class="stat-icon" :component="Server"/><strong>{{stats.online_nodes??'—'}} <em>/ {{stats.total_nodes??0}}</em></strong><small><span class="status-dot"></span> 按最后上报判断</small></article><article class="stat-card"><span class="stat-label">累计上传</span><n-icon class="stat-icon" :component="ArrowUpRight"/><strong>{{bytes(stats.up_bytes)}}</strong><small>原始用量 · 未应用倍率</small></article><article class="stat-card"><span class="stat-label">累计下载</span><n-icon class="stat-icon" :component="ArrowDownRight"/><strong>{{bytes(stats.down_bytes)}}</strong><small>原始用量 · 未应用倍率</small></article></section>
 <section class="overview-grid"><article class="surface usage-chart"><div class="section-heading"><div><h2>最近 7 天用量</h2><p>上传与下载合计 · {{zone}}</p></div><n-button text @click="$emit('usage')">查看明细 <template #icon><n-icon :component="ArrowRight"/></template></n-button></div><div v-if="bars.length" class="bar-chart"><div v-for="bar in bars" :key="bar.date" class="chart-column"><span class="chart-tooltip">{{bytes(bar.total)}}</span><div class="bar-track"><div class="bar-fill" :style="{height:bar.height+'%'}"></div></div><small>{{bar.date.slice(5)}}</small></div></div><n-empty v-else class="chart-empty" description="还没有用量记录"><template #extra><span class="muted">节点接入并上报后，趋势会显示在这里</span></template></n-empty><div class="chart-legend"><span></span>原始流量 <small>采集窗口按结束时间归档</small></div></article><article class="surface billing-summary"><span class="eyebrow">ACCOUNTING</span><h2>{{me.role==='admin'?'计费概览':'我的套餐'}}</h2><span class="billing-big">{{bytes(me.role==='admin'?stats.billed_bytes:me.used_bytes)}}</span><p>{{me.role==='admin'?'累计计费用量':'已使用额度'}}</p><n-progress v-if="me.role!=='admin'" type="line" :percentage="quotaProgress" :show-indicator="false"/><div class="billing-detail"><span>{{me.role==='admin'?'旧协议上报批次':'剩余额度'}}</span><strong>{{me.role==='admin'?stats.legacy_reports??0:bytes(Math.max(me.quota_bytes-me.used_bytes,0))}}</strong></div><div class="inline-info"><n-icon :component="Activity"/><p>计费用量已应用节点倍率。旧协议记录可能受重试与断线影响。</p></div></article></section>
 <article v-if="me.role==='admin'" class="surface"><div class="section-heading"><div><h2>节点动态</h2><p>最近完整窗口的平均速率</p></div><span class="muted small">每 30 秒刷新视图</span></div><div v-if="nodes.length" class="node-list"><div v-for="node in nodes.slice(0,6)" :key="node.id" class="node-row"><span class="node-symbol"><n-icon :component="Server" size="21"/></span><div class="node-name"><strong>{{node.name}}</strong><small>{{node.config.protocol?.toUpperCase()}} · #{{node.id}}</small></div><n-tag size="small" :bordered="false" :type="online(node)?'success':'default'">{{online(node)?'在线':'未连接'}}</n-tag><div class="node-speed"><strong>{{currentWindow(node)?bytes((Number(node.last_up_bytes)+Number(node.last_down_bytes))/Math.max(node.last_window_seconds,1))+'/s':'—'}}</strong><small>{{node.last_quality==='legacy'?'旧协议估算窗口':node.last_window_seconds+' 秒窗口'}}</small></div><div class="node-updated"><span>{{stamp(node.last_report_at)}}</span><small>最后收到上报</small></div></div></div><n-empty v-else description="尚未创建节点" class="empty-padding"/></article>
 </n-spin><p class="data-caption">最近更新 {{stamp(stats.updated_at)}} · 视图刷新不等于新的节点采样</p></template>
